sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float4 screen;
uniform float2 acScreenSize;
uniform float blurLength;
uniform float angle;
half4 main(float2 coord) {
    float strength = clamp(abs(blurLength), 0.0, 1.0);
    float2 texelSize = 1.0 / max(screen.zw, float2(1.0));
    float rad = radians(angle);
    float2 velocity = float2(cos(rad) * strength, -sin(rad) * strength);
    velocity.x *= acScreenSize.y / max(acScreenSize.x, 1.0);
    float speed = length(velocity / texelSize);
    int nSamples = int(clamp(speed, 1.01, 100.01));
    float2 uv = (coord - screen.xy) / max(screen.zw, float2(1.0));
    float4 outColor = image.eval(uv * screen.zw + screen.xy);
    for (int i = 1; i < 100; i++) {
        if (i >= nSamples) break;
        float2 off = velocity * (float(i) / float(max(nSamples - 1, 1)) - 0.5);
        float2 sampleCoord = uv - off;
        float inside = step(0.0, sampleCoord.x) * step(sampleCoord.x, 1.0) * step(0.0, sampleCoord.y) * step(sampleCoord.y, 1.0);
        outColor += image.eval(sampleCoord * screen.zw + screen.xy) * inside;
    }
    return outColor / float(max(nSamples, 1));
}
